#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>

using namespace std;

struct Edge {
    int from, to, capacity, cost, rev;
};

class Graph {
public:
    int vNum, src, sink;
    vector<vector<Edge>> adj;
    vector<int> dist, p, pEdge;

    Graph(int vNum, int src, int sink) : vNum(vNum), src(src), sink(sink) {
        adj.resize(vNum);
        dist.resize(vNum);
        p.resize(vNum);
        pEdge.resize(vNum);
    }

    void addEdge(int from, int to, int capacity, int cost) {
        Edge a{from, to, capacity, cost, (int)adj[to].size()};
        Edge b{to, from, 0, -cost, (int)adj[from].size()};
        adj[from].push_back(a);
        adj[to].push_back(b);
    }

    bool findCheapestPath() {
        fill(dist.begin(), dist.end(), INT_MAX);
        fill(p.begin(), p.end(), -1);
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        dist[src] = 0;
        pq.push({0, src});
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;
            for (int i = 0; i < (int)adj[u].size(); ++i) {
                Edge &e = adj[u][i];
                if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    p[e.to] = u;
                    pEdge[e.to] = i;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        return p[sink] != -1;
    }

    pair<int, int> augmentPath() {
        int flow = INT_MAX;
        for (int u = sink; u != src; u = p[u]) {
            Edge &e = adj[p[u]][pEdge[u]];
            flow = min(flow, e.capacity);
        }
        int pathCost = 0;
        for (int u = sink; u != src; u = p[u]) {
            Edge &e = adj[p[u]][pEdge[u]];
            e.capacity -= flow;
            adj[e.to][e.rev].capacity += flow;
            pathCost += e.cost * flow;
        }
        return {flow, pathCost};
    }

    pair<int, int> getMinCostMaxFlow() {
        int flow = 0, totalCost = 0;
        while (findCheapestPath()) {
            auto [f, c] = augmentPath();
            flow += f;
            totalCost += c;
        }
        return {flow, totalCost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    int letters = 'z' - 'a' + 1;
    vector<int> letCount(letters, 0);
    for (char c : s) {
        letCount[c - 'a']++;
    }
    vector<int> b(n);
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }

    int source = 0;
    int charOffSet = 1;
    int pairOffSet = charOffSet + letters;
    int sinkOffSet = pairOffSet + n / 2;
    int sink = sinkOffSet;
    int vNum = sinkOffSet + 1;

    Graph g(vNum, source, sink);

    for (int i = 0; i < letters; ++i) {
        g.addEdge(source, charOffSet + i, letCount[i], 0);
        for (int j = 0; j < n / 2; ++j) {
            char c1 = s[j];
            char c2 = s[n - j - 1];
            if (c1 == 'a' + i) {
                if (c1 == c2) {
                    g.addEdge(charOffSet + i, pairOffSet + j, 1, -max(b[j], b[n - j - 1]));
                } else {
                    g.addEdge(charOffSet + i, pairOffSet + j, 1, -b[j]);
                }
            } else {
                if (c2 == 'a' + i) {
                    g.addEdge(charOffSet + i, pairOffSet + j, 1, -b[n - j - 1]);
                } else {
                    g.addEdge(charOffSet + i, pairOffSet + j, 1, 0);
                }
            }
        }
    }

    for (int i = 0; i < n / 2; ++i) {
        g.addEdge(pairOffSet + i, sink, 2, 0);
    }

    auto [flow, totalCost] = g.getMinCostMaxFlow();
    cout << -totalCost << "\n";

    return 0;
}

